CREATE TEMPORARY VIEW a_source AS SELECT * FROM (VALUES (CAST(9007199254740993 AS BIGINT),CAST(12.3400 AS DECIMAL(24,4)),DECODE(UNHEX('2020e6b0b4f09f8c8a2020'), 'UTF-8'),'x'),(CAST(9007199254740993 AS BIGINT),CAST(12.3400 AS DECIMAL(24,4)),DECODE(UNHEX('2020e6b0b4f09f8c8a2020'), 'UTF-8'),'x'),(CAST(2 AS BIGINT),CAST(0.0100 AS DECIMAL(24,4)),DECODE(UNHEX('20204f275265696c6c792020'), 'UTF-8'),'x'),(CAST(NULL AS BIGINT),CAST(NULL AS DECIMAL(24,4)),CAST(NULL AS STRING),CAST(NULL AS STRING))) AS t(id,amount,name,junk);
CREATE TEMPORARY VIEW c_source AS SELECT * FROM (VALUES ('MiXeD',1,'first'),('MiXeD',1,'first'),('mixed',2,'second'),(CAST(NULL AS STRING),3,'null-first'),(CAST(NULL AS STRING),3,'null-first'),(CAST(NULL AS STRING),4,'null-second'),('H',5,CAST(NULL AS STRING))) AS t(`group`,id,payload);
CREATE TEMPORARY VIEW d_source AS SELECT * FROM (VALUES ('Ab',CAST(1 AS BIGINT)),('Ab',CAST(1 AS BIGINT)),('ab',CAST(1 AS BIGINT)),(CAST(NULL AS STRING),CAST(2 AS BIGINT)),(CAST(NULL AS STRING),CAST(2 AS BIGINT)),('Other',CAST(3 AS BIGINT))) AS t(id,n);
CREATE TABLE `a_out` (`id` BIGINT, `amount` DECIMAL(24,4), `名称` STRING, `bucket` STRING, `marker` STRING, `trace` STRING, `which` STRING, `value` STRING) USING JSON OPTIONS (path '/tmp/datahub-control-987a6d0641eb-spark-all/data/a_out');
CREATE TABLE `c_out` (`group` STRING, `id` INT, `payload` STRING) USING JSON OPTIONS (path '/tmp/datahub-control-987a6d0641eb-spark-all/data/c_out');
CREATE TABLE `d_out` (`id` STRING, `n` BIGINT) USING JSON OPTIONS (path '/tmp/datahub-control-987a6d0641eb-spark-all/data/d_out');
INSERT INTO `a_out` (`id`, `amount`, `名称`, `bucket`, `marker`, `trace`, `which`, `value`) SELECT `id`, `amount`, `名称`, `bucket`, `marker`, `trace`, `which`, `value` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `名称` AS `名称`, `bucket` AS `bucket`, `marker` AS `marker`, `trace` AS `trace`, `which` AS `which`, `value` AS `value` FROM (SELECT dh_base.`id` AS `id`, dh_base.`amount` AS `amount`, dh_base.`名称` AS `名称`, dh_base.`bucket` AS `bucket`, dh_base.`marker` AS `marker`, dh_base.`trace` AS `trace`, dh_unpivot.dh_pair.dh_key AS `which`, dh_unpivot.dh_pair.dh_value AS `value` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `名称`, `mapped` AS `mapped`, `copied` AS `copied`, `bucket` AS `bucket`, `marker` AS `marker`, `trace` AS `trace` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `trace` AS `trace`, `name` AS `mapped`, `bucket` AS `bucket`, `marker` AS `marker`, `mapped` AS `copied` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `trace` AS `trace`, `mapped` AS `mapped`, `bucket` AS `bucket`, DECODE(UNHEX('4f275265696c6c795c2431f09f9880'), 'UTF-8') AS `marker` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `trace` AS `trace`, `mapped` AS `mapped`, CASE WHEN `amount` IS NOT NULL AND `amount` >= 0 AND `amount` < 1 THEN 'small' WHEN `amount` IS NOT NULL AND `amount` >= 1 AND `amount` < 20 THEN 'big' ELSE 'missing' END AS `bucket` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `trace` AS `trace`, CASE WHEN COALESCE(CAST(`name` AS STRING), '') = '水🌊' THEN '江河' ELSE CAST(`name` AS STRING) END AS `mapped` FROM (SELECT DISTINCT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `trace` AS `trace` FROM (SELECT `id` AS `id`, `amount` AS `amount`, REGEXP_REPLACE(CAST(`name` AS STRING), DECODE(UNHEX('5e5b002d205d2b7c5b002d205d2b24'), 'UTF-8'), '') AS `name`, `trace` AS `trace` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `junk` AS `junk`, `trace` AS `trace` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `junk` AS `junk`, DECODE(UNHEX('e5ad90e6b581e7a88b274f5c24f09f9880'), 'UTF-8') AS `trace` FROM (SELECT `id` AS `id`, `amount` AS `amount`, `name` AS `name`, `junk` AS `junk` FROM (SELECT `id`, `amount`, `name`, `junk` FROM `a_source`) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_stage) dh_base LATERAL VIEW EXPLODE(ARRAY(NAMED_STRUCT('dh_key', 'mapped', 'dh_value', dh_base.`mapped`), NAMED_STRUCT('dh_key', 'copied', 'dh_value', dh_base.`copied`))) dh_unpivot AS dh_pair) dh_stage ORDER BY `id` ASC NULLS LAST, `which` ASC NULLS LAST) dh_output ORDER BY `id` ASC NULLS LAST, `which` ASC NULLS LAST;
INSERT INTO `c_out` (`group`, `id`, `payload`) SELECT `group`, `id`, `payload` FROM (SELECT `group` AS `group`, `id` AS `id`, `payload` AS `payload` FROM (SELECT `group`, `id`, `payload` FROM (SELECT dh_dedup_input.*, ROW_NUMBER() OVER (PARTITION BY LOWER(`group`) ORDER BY `id` ASC NULLS LAST) AS `dh_dedup_row` FROM (SELECT `group`, `id`, `payload` FROM (SELECT dh_order_input.*, COUNT(*) OVER (PARTITION BY `id`) AS `dh_unique_count` FROM (SELECT DISTINCT `group`, `id`, `payload` FROM (SELECT `group` AS `group`, `id` AS `id`, `payload` AS `payload` FROM (SELECT `group`, `id`, `payload` FROM `c_source`) dh_stage) dh_dedup_distinct) dh_order_input) dh_order_checked WHERE CASE WHEN `dh_unique_count` = 1 THEN TRUE ELSE RAISE_ERROR('唯一排序字段存在重复值') END) dh_dedup_input) dh_dedup_first WHERE `dh_dedup_row` = 1) dh_stage ORDER BY `id` ASC NULLS LAST) dh_output ORDER BY `id` ASC NULLS LAST;
INSERT INTO `d_out` (`id`, `n`) SELECT `id`, `n` FROM (SELECT `id` AS `id`, `n` AS `n` FROM (SELECT `id`, `n` FROM (SELECT dh_dedup_input.*, ROW_NUMBER() OVER (PARTITION BY LOWER(`id`), `n` ORDER BY `id` ASC NULLS LAST) AS `dh_dedup_row` FROM (SELECT `id`, `n` FROM (SELECT dh_order_input.*, COUNT(*) OVER (PARTITION BY `id`) AS `dh_unique_count` FROM (SELECT DISTINCT `id`, `n` FROM (SELECT `id` AS `id`, `n` AS `n` FROM (SELECT `id`, `n` FROM `d_source`) dh_stage) dh_dedup_distinct) dh_order_input) dh_order_checked WHERE CASE WHEN `dh_unique_count` = 1 THEN TRUE ELSE RAISE_ERROR('唯一排序字段存在重复值') END) dh_dedup_input) dh_dedup_first WHERE `dh_dedup_row` = 1) dh_stage ORDER BY `id` ASC NULLS LAST) dh_output ORDER BY `id` ASC NULLS LAST;